import numpy as np
fs={'1':np.ones_like(t),'t':t,'t2':t**2,'sin':np.sin(t),'cos':np.cos(t),'exp-t':np.exp(-t),'sqrt':np.sqrt(t),'log':np.log(t),'1/t':1/t}
cols=[];names=[]
for i in [-2,-1,0,1,2,3]:
    for k,f in fs.items():
        cols.append(A**i*f); names.append((i,k))
X=np.column_stack(cols)
c,*_=np.linalg.lstsq(X,dA_dt,rcond=None)
print("nmse",np.mean((dA_dt-X@c)**2)/np.var(dA_dt))
sel=[];rem=list(range(len(cols)))
for step in range(6):
    best=None
    for k in rem:
        Xs=np.column_stack([cols[q] for q in sel+[k]])
        cc,*_=np.linalg.lstsq(Xs,dA_dt,rcond=None)
